result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/monitor.py", "content": """"Freshness / completeness / volume monitoring over snapshots.jsonl.

Rules:
  FRESHNESS_LATE    loaded_at is more than 6h after the end of `day`.
  MISSING_SNAPSHOT  a table has no row for a day inside the global day range.
  VOLUME_DROP       row_count < 0.7 * median of the trailing (up to) 7 prior
                    daily counts for the same table. Days 1-7 are exempt
                    (insufficient history). Median, not mean: a single spike
                    in the trailing window must not mask or fabricate drops.

Emits findings.json: [{"type", "table", "day", "detail"}, ...]
"""

import json
import statistics
from datetime import date, datetime, timedelta

DAY = timedelta(days=1)
LATE_GRACE = timedelta(hours=6)
VOLUME_RATIO = 0.7
TRAILING_WINDOW = 7
HISTORY_EXEMPT_DAYS = 7  # calendar days 1-7 never get VOLUME_DROP


def parse_ts(s):
    return datetime.fromisoformat(s.replace("Z", "+00:00"))


def load_rows(path):
    rows = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows


def check_freshness(rows):
    findings = []
    for r in rows:
        day_end = datetime.combine(date.fromisoformat(r["day"]) + DAY,
                                   datetime.min.time())
        if parse_ts(r["loaded_at"]) > day_end + LATE_GRACE:
            findings.append({
                "type": "FRESHNESS_LATE",
                "table": r["table"],
                "day": r["day"],
                "detail": f"loaded_at {r['loaded_at']} is >6h after day end",
            })
    return findings


def check_completeness(rows, first_day, last_day):
    by_table_day = {(r["table"], r["day"]) for r in rows}
    findings = []
    n = (last_day - first_day).days + 1
    for table in sorted({r["table"] for r in rows}):
        for i in range(n):
            day = (first_day + timedelta(days=i)).isoformat()
            if (table, day) not in by_table_day:
                findings.append({
                    "type": "MISSING_SNAPSHOT",
                    "table": table,
                    "day": day,
                    "detail": "no snapshot row for this day",
                })
    return findings


def check_volume(rows, first_day):
    """VOLUME_DROP: count < 0.7 * trailing-7-day MEDIAN; days 1-7 exempt."""
    by_table = {}
    for r in rows:
        by_table.setdefault(r["table"], []).append(r)
    findings = []
    for table in sorted(by_table):
        series = sorted(by_table[table], key=lambda r: r["day"])
        history = []  # prior daily counts in chronological order
        for r in series:
            day_index = (date.fromisoformat(r["day"]) - first_day).days + 1
            if day_index > HISTORY_EXEMPT_DAYS and len(history) >= TRAILING_WINDOW:
                baseline = statistics.median(history[-TRAILING_WINDOW:])
                if r["row_count"] < VOLUME_RATIO * baseline:
                    findings.append({
                        "type": "VOLUME_DROP",
                        "table": table,
                        "day": r["day"],
                        "detail": (f"row_count {r['row_count']} < "
                                   f"{VOLUME_RATIO:.0%} of trailing-7-day median "
                                   f"({baseline:.0f})"),
                    })
            history.append(r["row_count"])
    return findings


def run(rows):
    first_day = min(date.fromisoformat(r["day"]) for r in rows)
    last_day = max(date.fromisoformat(r["day"]) for r in rows)
    findings = []
    findings += check_freshness(rows)
    findings += check_completeness(rows, first_day, last_day)
    findings += check_volume(rows, first_day)
    order = {"MISSING_SNAPSHOT": 0, "FRESHNESS_LATE": 1, "VOLUME_DROP": 2}
    findings.sort(key=lambda f: (order[f["type"]], f["table"], f["day"]))
    return findings


def main():
    findings = run(load_rows("snapshots.jsonl"))
    with open("findings.json", "w") as f:
        json.dump(findings, f, indent=2)
        f.write("\n")
    for x in findings:
        print(f'{x["type"]:16s} {x["table"]:8s} {x["day"]}  {x["detail"]}')
    print(f"{len(findings)} finding(s) -> findings.json")


if __name__ == "__main__":
    main()
